/bin/zsh -lc "cat > /private/tmp/maya-interaction-check.js <<'JS'
const fs = require('fs');
const vm = require('vm');
const assert = require('assert');
class Element {
 constructor(dataset={}) { this.dataset=dataset;this.listeners={};this.attributes={};this.textContent=''; }
 addEventListener(event,handler){this.listeners[event]=handler}
 setAttribute(key,value){this.attributes[key]=value}
 replaceChildren(...children){this.children=children}
 showModal(){this.open=true}
 close(){this.open=false}
 click(){this.listeners.click({target:this})}
}
const filters=['All','Design','Data','Freelancing','Field notes'].map(filter=>new Element({filter}));
const posts=['Design','Field notes','Design','Data','Field notes','Freelancing'].map(tag=>new Element({tag}));
const noteButtons=['gloves','banking','charts','tram','pricing'].map(post=>new Element({post}));
const selectors={};
for(const s of ['.theme-toggle','meta[name=\"theme-color\"]','.post-count','#newsletter-form','#subscribe-message','#reading-dialog','#dialog-title','#dialog-meta','#dialog-body','.dialog-close'])selectors[s]=new Element();
const root=new Element({theme:'light'});
const saved={};
const document={documentElement:root,querySelector:s=>{assert(selectors[s],s);return selectors[s]},querySelectorAll:s=>({'.filter':filters,'.post':posts,'[data-post]':noteButtons}[s]),createElement:()=>new Element()};
const html=fs.readFileSync('index.html','utf8');
const scripts=[...html.matchAll(/<script>([\\s\\S]*?)<\\/script>/g)];
vm.runInNewContext(scripts[1][1],{document,localStorage:{setItem:(k,v)=>saved[k]=v}});
selectors['.theme-toggle'].click();
assert.equal(root.dataset.theme,'dark');assert.equal(saved['maya-theme'],'dark');assert.equal(selectors['.theme-toggle'].attributes['aria-pressed'],'true');
selectors['.theme-toggle'].click();assert.equal(root.dataset.theme,'light');
filters[1].click();assert.equal(posts.filter(p=>"'!p.hidden).length,2);assert.equal(filters[1].attributes['"'aria-pressed'],'true');assert.equal(filters[0].attributes['aria-pressed'],'false');
filters[2].click();assert.equal(posts.filter(p=>"'!p.hidden).length,1);assert.equal(selectors['"'.post-count'].textContent,'1 post · Data');
filters[4].click();assert.equal(posts.filter(p=>"'!p.hidden).length,2);
filters[0].click();assert.equal(posts.filter(p=>!p.hidden).length,6);
let prevented=false;selectors['"'#newsletter-form'].listeners.submit({preventDefault(){prevented=true}});assert(prevented);assert(selectors['#subscribe-message'].textContent.includes('does not send or store'));
for(const b of noteButtons){b.click();assert(selectors['#reading-dialog'].open);assert(selectors['#dialog-title'].textContent.length>10);assert.equal(selectors['#dialog-body'].children.length,3);selectors['.dialog-close'].click();assert("'!selectors['"'#reading-dialog'].open)}
console.log('Interaction checks passed: theme toggle and persistence, all filters, newsletter feedback, five reading dialogs and close controls.');
