from pathlib import Path
from html.parser import HTMLParser
class Structure(HTMLParser):
 def __init__(self):super().__init__();self.stack=[]
 def handle_starttag(self,t,a):
  if t not in {'meta','link','input','br','hr','path','circle','rect','line','ellipse','polyline','polygon','stop','use','img','wbr','source','area','base','col','embed','param','track'}:self.stack.append(t)
 def handle_startendtag(self,t,a):pass
 def handle_endtag(self,t):
  assert self.stack and self.stack[-1]==t,(t,self.stack[-4:])
  self.stack.pop()
p=Structure();p.feed(Path('index.html').read_text());assert not p.stack
print('Element nesting passed. Workspace output:', ', '.join(x.name for x in Path('.').iterdir() if x.is_file()))
